-- ---------------------------------------------------------------------
-- Carga de las cuatro hojas del libro F-EST-01/07 de Calidad
--
-- Generado desde la planilla del 2 de octubre de 2026, fila por fila y
-- tal como esta cargada. Las hojas 4.1 Contexto y 4.2 Partes
-- Interesadas quedan afuera, como se indico.
--
-- LOS DATOS VAN EN JSON y se recorren con un bucle, en vez de doscientas
-- lineas de `insert` repetidas. No es por brevedad: asi la lista de
-- columnas se escribe una sola vez, y el dia que Calidad agregue una
-- fila a la planilla se agrega un objeto y nada mas.
--
-- CUATRO COSAS QUE LA PLANILLA DICE Y LA BASE NO PODIA REPRESENTAR TAL
-- CUAL, y como se resolvio cada una:
--
--   · EL PROCESO. La planilla usa otro mapa de procesos que la intranet
--     —veintitres contra diecinueve, y los mismos codigos significan
--     cosas distintas: MP-EST-01 es «Informacion Documentada» en la
--     intranet y «Planificacion y Control del SGC» en la planilla— y
--     varias filas nombran dos procesos a la vez
--     («MP-MIS-01 / MP-MIS-03»), que una clave ajena no puede
--     representar. Va en `proceso_declarado`, en texto y sin
--     interpretar; `proceso_id` queda vacio hasta que Calidad confirme
--     el mapa definitivo. Asi los datos entran completos hoy y no se
--     toca ni la Lista Maestra ni los veintiun documentos ya cargados.
--
--   · EL RESPONSABLE. La planilla nombra cargos, no personas:
--     «Asistente de Gestion Regulatoria», «Jefe de Operaciones y
--     Logistica». En la intranet hay dos usuarios, porque el perfil se
--     crea en el primer ingreso. Va en `responsable_declarado` y se
--     vincula cuando esas personas entren.
--
--   · EL PLAZO «PERMANENTE». Varias acciones son controles que no
--     terminan y la columna de plazo dice esa palabra en vez de una
--     fecha. Va como bandera y el plazo queda vacio.
--
--   · «DIFERIDA» en la decision de abordar una oportunidad. La columna
--     admite Si, No y Diferida, y la base tenia un booleano: una
--     oportunidad diferida no es una que se decidio no abordar, es una
--     que espera la Revision por la Direccion. Queda la palabra exacta
--     en `decision_declarada`.
--
-- EL N.º DE LA PLANILLA NO SE CARGA: el codigo lo genera la base,
-- correlativo y por empresa, como pidio Calidad.
--
-- Es idempotente: cada bloque borra lo que cargo antes y vuelve a
-- cargarlo. Y es atomico: si una fila falla, no entra ninguna.
-- ---------------------------------------------------------------------

do $carga$
declare
  v_empresa uuid;
  v_autor uuid;
  v_codigo text;
  f jsonb;
begin
  select id into v_empresa from public.empresas order by creado_en limit 1;
  select id into v_autor from public.usuarios
   where correo ilike 'carlos%' order by creado_en limit 1;
  if v_autor is null then
    select id into v_autor from public.usuarios order by creado_en limit 1;
  end if;

  -- Hoja 6.1.2 · Matriz de Riesgos (F-EST-01-03)
  delete from public.riesgos where tipo = 'riesgo' and proceso_declarado is not null;

  for f in select * from jsonb_array_elements('[{"descripcion":"Vencimiento o cancelación de oficio de una habilitación (comerciante, importador, polígono, centro de instrucción, taller o instructores).","fecha":"2026-10-02","proceso":"MP-MIS-04 Gestión Regulatoria","origen":"Contexto de la Organización","causas":"No iniciar la renovación a tiempo o tener vencido un requisito (póliza, patente, monitoreo, cumplimiento tributario).","consecuencias":"Cese de la actividad afectada y entrega del inventario a la DIGEMABEL.","disrupcion":true,"probabilidad":2,"severidad":5,"tratamiento":"cambiar_probabilidad","accion":"Tablero de Vencimientos con alerta a 90 días y revisión mensual; renovación iniciada 3 meses antes. CONTINUIDAD: si una habilitación cae, se suspende solo esa actividad, se avisa a los clientes afectados y se tramita la rehabilitación.","responsable":"Asistente de Gestión Regulatoria","plazo":"2027-01-31","permanente":false,"proceso_accion":"MP-MIS-04 Gestión Regulatoria","prob_residual":null,"sev_residual":null,"fecha_medicion":"2027-06-30","estado":"en_tratamiento","titulo":"Vencimiento o cancelación de oficio de una habilitación (comerciante, importador, polígono, centro de instrucción, ta…"},{"descripcion":"Bloqueo del usuario de la empresa en el SID.","fecha":"2026-10-02","proceso":"MP-MIS-04 Gestión Regulatoria","origen":"Contexto de la Organización","causas":"Confirmación de recepción fuera de los 15 días de vigencia del permiso u otra falta registrada.","consecuencias":"No se puede vender, recibir ni trasladar Material Controlado.","disrupcion":true,"probabilidad":3,"severidad":5,"tratamiento":"cambiar_probabilidad","accion":"Control de permisos con aviso al día 10; suplente formado en el SID. CONTINUIDAD: pedido inmediato de desbloqueo a la DIGEMABEL, aviso a los clientes con entregas pendientes y venta solo de Material No Controlado mientras dure.","responsable":"Asistente de Gestión Regulatoria","plazo":null,"permanente":true,"proceso_accion":"MP-MIS-04 Gestión Regulatoria","prob_residual":null,"sev_residual":null,"fecha_medicion":"2027-06-30","estado":"en_tratamiento","titulo":"Bloqueo del usuario de la empresa en el SID"},{"descripcion":"Caída del SID por más de 2 días hábiles.","fecha":"2026-10-02","proceso":"MP-MIS-05 Ventas Multicanal","origen":"Contexto de la Organización","causas":"Falla del sistema de la DIGEMABEL.","consecuencias":"Ventas de armas detenidas y clientes sin respuesta.","disrupcion":true,"probabilidad":2,"severidad":4,"tratamiento":"cambiar_consecuencia","accion":"CONTINUIDAD (Art. 91): trámite en papel solo para Clases 1 y 2, foto del cliente con el arma y el carnet, envío a la DIGEMABEL en 48 h; se informa al cliente el nuevo plazo. Se detalla en el I-MIS-04-01 Operación del SID.","responsable":"Asistente de Gestión Regulatoria","plazo":"2027-06-30","permanente":false,"proceso_accion":"MP-MIS-04 Gestión Regulatoria","prob_residual":null,"sev_residual":null,"fecha_medicion":"2027-12-31","estado":"identificado","titulo":"Caída del SID por más de 2 días hábiles"},{"descripcion":"Diferencia entre el inventario físico, el ERP y el SID.","fecha":"2026-10-02","proceso":"MP-MIS-01 Categorización y Control de Inventario","origen":"Partes Interesadas","causas":"Errores de registro, faltantes o hurto interno.","consecuencias":"Falta grave (Art. 247 c), bloqueo o clausura.","disrupcion":true,"probabilidad":2,"severidad":5,"tratamiento":"cambiar_probabilidad","accion":"Conteo cíclico mensual del Depósito Seguro contra ERP y SID; ratificación semestral; toda diferencia es No Conformidad Mayor y el ERP no se ajusta sin el SID. CONTINUIDAD: aviso inmediato a Gestión Regulatoria y regularización ante la DIGEMABEL.","responsable":"Jefe de Operaciones y Logística","plazo":null,"permanente":true,"proceso_accion":"MP-MIS-01 / MP-MIS-03","prob_residual":null,"sev_residual":null,"fecha_medicion":"2027-07-31","estado":"en_tratamiento","titulo":"Diferencia entre el inventario físico, el ERP y el SID"},{"descripcion":"Siniestro o robo en el depósito o en el local.","fecha":"2026-10-02","proceso":"MP-SOP-03 Infraestructura y Tecnología","origen":"Contexto de la Organización","causas":"Intrusión, incendio o falla eléctrica.","consecuencias":"Pérdida de Material Controlado, riesgo para terceros y sanciones.","disrupcion":true,"probabilidad":2,"severidad":5,"tratamiento":"compartir","accion":"Póliza contra robo e incendio; monitoreo 24 h, CCTV, alarmas y extintores revisados cada trimestre; aviso a la DIGEMABEL en 24 h y 72 h. CONTINUIDAD: plan de evacuación, resguardo del material y atención a clientes por canales remotos.","responsable":"Supervisor de Logística e Infraestructura","plazo":null,"permanente":true,"proceso_accion":"MP-SOP-03 Infraestructura y Tecnología","prob_residual":null,"sev_residual":null,"fecha_medicion":"2027-12-31","estado":"en_tratamiento","titulo":"Siniestro o robo en el depósito o en el local"},{"descripcion":"Robo, accidente o extravío de Material Controlado en tránsito.","fecha":"2026-10-02","proceso":"MP-MIS-06 Despacho y Entrega de Mercadería","origen":"Contexto de la Organización","causas":"Asalto, accidente vial o error de la transportadora.","consecuencias":"Pérdida del material, sanción y reclamo del cliente.","disrupcion":true,"probabilidad":2,"severidad":5,"tratamiento":"compartir","accion":"Solo transportadoras aprobadas con póliza; sin despachos viernes ni sábados salvo F-MIS-06-01; plan IT1 a IT6 (denuncia en 24 h y aviso a la DIGEMABEL en 24/72 h).","responsable":"Supervisor de Logística e Infraestructura","plazo":null,"permanente":true,"proceso_accion":"MP-MIS-06 Despacho y Entrega de Mercadería","prob_residual":null,"sev_residual":null,"fecha_medicion":"2027-12-31","estado":"en_tratamiento","titulo":"Robo, accidente o extravío de Material Controlado en tránsito"},{"descripcion":"Clausura temporal del local.","fecha":"2026-10-02","proceso":"MP-MIS-04 Gestión Regulatoria","origen":"Contexto de la Organización","causas":"Inspección de