ocimiento climático en la planificació…"},{"descripcion":"Formar multiplicadores internos que repliquen las capacitaciones externas.","fecha":"2026-10-02","proceso":"MP-SOP-02 Gestión del Capital Humano","origen":"Sugerencia de un Colaborador","efecto":"Menor costo de formación y conocimiento compartido.","beneficio":3,"factibilidad":5,"alineacion":"media","abordar":true,"decision":"Sí","accion":"Cada capacitación externa termina con una réplica interna registrada en el módulo Personas.","recursos":"Tiempo del colaborador capacitado","responsable":"Jefe de Capital Humano","plazo":null,"permanente":true,"proceso_accion":"MP-SOP-02","resultado":null,"fecha_medicion":"2027-12-31","estado":"en_tratamiento","titulo":"Formar multiplicadores internos que repliquen las capacitaciones externas"}]'::jsonb) loop
    select public.siguiente_codigo_riesgo(v_empresa) into v_codigo;
    insert into public.riesgos (
