do $carga$
declare
  v_empresa uuid;
  v_autor uuid;
  v_codigo text;
  f jsonb;
begin
  select id into v_empresa from public.empresas order by creado_en limit 1;
  select id into v_autor from public.usuarios
   where correo ilike 'carlos%' order by creado_en limit 1;
  if v_autor is null then
    select id into v_autor from public.usuarios order by creado_en limit 1;
  end if;

  -- Hoja 6.2 · Objetivos de la Calidad e Indicadores (F-EST-01-05)
  --
  -- SE BORRA LO QUE HABIA. Los treinta objetivos del PE 2026 que
  -- estaban cargados se retiran: lo decidio Direccion al pasar esta
  -- planilla, que es la que vale.
  --
  -- Los ocho objetivos salen de la columna B: las filas que empiezan
  -- con «O1» a «O8» los declaran. Las que dicen «Desempeno del proceso»
  -- son indicadores de proceso y no cuelgan de ningun objetivo de
  -- calidad: su `objetivo_id` queda vacio a proposito.
  delete from public.indicadores;
  delete from public.objetivos;

  for f in select * from jsonb_array_elements('[{"clave":"O1","nombre":"Mantener todas las habilitaciones vigentes","nivel":"estrategico","proceso":"MP-MIS-04 Gestión Regulatoria","codigo":"OBJ-2027-01"},{"clave":"O2","nombre":"Asegurar la trazabilidad del Material Controlado","nivel":"estrategico","proceso":"MP-MIS-01 / MP-MIS-03","codigo":"OBJ-2027-02"},{"clave":"O3","nombre":"Vender armas solo con todos los controles legales","nivel":"estrategico","proceso":"MP-MIS-05 Ventas Multicanal","codigo":"OBJ-2027-03"},{"clave":"O4","nombre":"Fortalecer la cultura de la calidad y la ética","nivel":"estrategico","proceso":"MP-SOP-02 Gestión del Capital Humano","codigo":"OBJ-2027-04"},{"clave":"O5","nombre":"Aumentar la satisfacción del cliente","nivel":"estrategico","proceso":"MP-EST-04 Experiencia y Fidelización de Clientes","codigo":"OBJ-2027-05"},{"clave":"O6","nombre":"Operar sin accidentes ni pérdidas de Material Controlado","nivel":"estrategico","proceso":"MP-MIS-08 / MP-SOP-03 / MP-MIS-06","codigo":"OBJ-2027-06"},{"clave":"O7","nombre":"Asegurar la competencia del personal","nivel":"estrategico","proceso":"MP-SOP-02 Gestión del Capital Humano","codigo":"OBJ-2027-07"},{"clave":"O8","nombre":"Resolver las fallas de raíz y a tiempo","nivel":"estrategico","proceso":"MP-EST-03 No Conformidades y Acciones Correctivas","codigo":"OBJ-2027-08"}]'::jsonb) loop
    insert into public.objetivos (
      empresa_id, codigo, nombre, descripcion, anio, nivel, estado, es_demostracion
    ) values (
      v_empresa, f->>'codigo', f->>'nombre',
      'Objetivo de la calidad ' || (f->>'clave') || ' · ' || coalesce(f->>'proceso', ''),
      2027, f->>'nivel', 'en_curso', false
    );
  end loop;

