ento queda vacío; leer como Cumple."},{"codigo":"IND-039","nombre":"Asociados de negocio evaluados en plazo","objetivo":"Desempeño del proceso","codigo_objetivo":null,"nivel":"tactico","proceso":"MP-SOP-08 Compras Locales y Evaluación de Terceros","formula":"Asociados críticos evaluados / programados x 100","unidad":"%","linea_base":null,"meta":100,"sentido":"mayor_mejor","consolidacion":"ultimo","frecuencia":"semestral","fuente":"Evaluaciones de proveedores","responsable":"Gerente de Administración y Finanzas","observaciones":null},{"codigo":"IND-040","nombre":"Arqueos con diferencias sin justificar","objetivo":"Desempeño del proceso","codigo_objetivo":null,"nivel":"operativo","proceso":"MP-SOP-09 Gestión de Caja y Tesorería","formula":"N.º de arqueos con diferencias no justificadas","unidad":"N.º","linea_base":null,"meta":0,"sentido":"menor_mejor","consolidacion":"suma","frecuencia":"mensual","fuente":"Planillas de arqueo","responsable":"Analista de Tesorería","observaciones":"Meta 0: con resultado 0 el % de cumplimiento queda vacío; leer como Cumple."}]'::jsonb) loop
    insert into public.indicadores (
      empresa_id, codigo, nombre, descripcion, objetivo_id, nivel,
      proceso_declarado, formula, unidad, linea_base, meta, sentido,
      consolidacion, frecuencia, fuente_dato, responsable_declarado,
      observaciones, activo, es_demostracion
    ) values (
      v_empresa, f->>'codigo', f->>'nombre', f->>'objetivo',
      (select id from public.objetivos
        where empresa_id = v_empresa and codigo = f->>'codigo_objetivo'),
      f->>'nivel', f->>'proceso', f->>'formula', f->>'unidad',
      (f->>'linea_base')::numeric, (f->>'meta')::numeric,
      (f->>'sentido')::public.sentido_indicador,
      (f->>'consolidacion')::public.consolidacion_indicador,
      (f->>'frecuencia')::public.frecuencia_medicion,
      f->>'fuente', f->>'responsable', f->>'observaciones', true, false
    );
  end loop;

  raise notice 'Objetivos: % · indicadores: %',
    (select count(*) from public.objetivos), (select count(*) from public.indicadores);
end $carga$;

do $carga$
declare
  v_empresa uuid;
  v_autor uuid;
  v_codigo text;
  f jsonb;
begin
  select id into v_empresa from public.empresas order by creado_en limit 1;
  select id into v_autor from public.usuarios
   where correo ilike 'carlos%' order by creado_en limit 1;
  if v_autor is null then
    select id into v_autor from public.usuarios order by creado_en limit 1;
  end if;

  -- Hoja 6.2.2 · Plan de Accion para el Logro de los Objetivos
  -- (F-EST-01-06) · los cinco incisos del apartado 6.2.2 de la norma.
  --
  -- La ultima fila dice «Todos» en la columna del objetivo: aplica a
  -- los ocho a la vez, asi que su `objetivo_id` queda vacio y la
  -- palabra se conserva en `objetivo_declarado`.
  delete from public.objetivo_planes;

