    ) values (
      v_empresa,
      (select id from public.objetivos
        where empresa_id = v_empresa and codigo = f->>'codigo_objetivo'),
      f->>'objetivo', f->>'que', f->>'recursos', f->>'responsable',
      (f->>'fecha_fin')::date, f->>'como', (f->>'fecha_real')::date,
